const sourceById = new Map(italianMaster.chapters.map((chapter) => [chapter.id, chapter]))

const buildChapter = (id, translation) => {
  const source = sourceById.get(id)
  if (!source) throw new Error(`Missing Italian source chapter: ${id}`)
  if (source.blocks.length !== translation.texts.length) {
    throw new Error(`EN block count mismatch for ${id}: IT=${source.blocks.length} EN=${translation.texts.length}`)
  }

  return {
    title: translation.title,
    blocks: source.blocks.map((block, index) => ({
      ...block,
      text: translation.texts[index],
    })),
  }
}

export const englishChapters01to10 = Object.fromEntries(
  Object.entries(translationData).map(([id, translation]) => [id, buildChapter(id, translation)]),
)
